-- =============================================
-- Ski Alpen (pb/ski.html, arcade id "ski"): leaderboards are TIMES.
-- Generated by scripts/ski/make_sql.py from the baked resorts. NOT applied by the builder: the reviewer runs it.
-- Idempotent.
--
-- 1. merge_score_is_better: ski-* boards are lower-is-better (like memory / maze / reaction). Without this the keep-best trigger
--    would keep the SLOWEST time and the anti-cheat would read a faster time as a worse one.
-- 2. is_idle_game: ski-* boards skip only the 1.5x "new #1" ratio rule. Boards are per piste (140+ of them) and young: a first good
--    skier beats a few casual runs by far more than 1.5x (150 s -> 95 s), which would ban honest players. The young-account rule stays.
--    Instead ski-* times get:
-- 3. a floor per board: a time faster than the piste length / 33 m/s (the physics hard cap) along the piste line is impossible (the
--    game never posts one either: pb/ski/progress.js minRunMs) and is dropped by a trigger. Unknown ski-* boards and a bare "ski" board
--    are dropped too (security review M2, 22 Nov 2026: they used to get a 20 s floor).
--
-- 4. (round 4A) one snow park board per resort, ski-<resort>-park: park POINTS (higher is better for the player), stored as
--    1,000,000 - points so the board stays lower-is-better like every other ski-* board (no change to merge_score_is_better, the
--    arcade's GAMES entry or the keep-best trigger; the client format "skipark" prints the points). Its row in ski_board_floors holds
--    the stored range: min_ms = 1,000,000 - 250,000 (the points ceiling: a perfect run with every feature scores far less), max_ms =
--    999,999 (at least 1 point). The game never posts outside it either (pb/ski/modes/park.js validParkPoints).
--
-- 5. (security review H2, 22 Nov 2026) scores_guard_row (security-fix-scores-v1.sql: at most 300 score rows per player) would stop
--    EVERY game's saves for a player who skis 300 of the 1356 boards. Here it is replaced by the same function with one exception: a
--    ski-* row counts only when its board is in ski_board_floors, and ski-* rows are not part of the 300. security-fix-scores-v1.sql
--    carries the identical function (guarded by to_regclass), so running the two files in any order gives the same result.
--
-- Keep the game lists in step with the latest versions: scores-numeric-v1.sql (merge_score_is_better) and
-- anticheat-webcam-v1.sql (is_idle_game).
-- =============================================

create or replace function public.merge_score_is_better(p_game text, p_new double precision, p_old double precision)
returns boolean language sql immutable as $$
  select case when p_game in ('memory', 'maze', 'reaction') or p_game like 'ski-%'
              then p_new < p_old else p_new > p_old end
$$;
revoke all on function public.merge_score_is_better(text, double precision, double precision) from public, anon, authenticated;
grant execute on function public.merge_score_is_better(text, double precision, double precision) to service_role;

create or replace function public.is_idle_game(p_game text)
returns boolean language sql immutable as $$
  select p_game in ('idle-empire', 'cookie-clicker', 'bus-tycoon', 'park')
      or p_game like 'webcam-%'   -- anticheat-webcam-v1.sql (Kamera-Arcade)
      or p_game like 'ski-%'      -- ski-v1.sql: per-piste time boards, guarded by ski_time_floor instead
$$;

create table if not exists public.ski_board_floors (
  board text primary key check (board like 'ski-%'),
  min_ms integer not null check (min_ms >= 0)
);
-- round 4A: an upper bound per board (the snow park boards); null = the general 1 h ceiling
alter table public.ski_board_floors add column if not exists max_ms integer check (max_ms is null or max_ms >= min_ms);
alter table public.ski_board_floors enable row level security;
revoke all on table public.ski_board_floors from anon, authenticated;

create or replace function public.ski_time_floor()
returns trigger language plpgsql security definer set search_path = public as $$
declare floor_ms integer; ceil_ms integer;
begin
  if new.game_id = 'ski' then
    if tg_op = 'UPDATE' then return old; end if;
    return null;
  end if;
  if new.game_id not like 'ski-%' then return new; end if;
  select f.min_ms, f.max_ms into floor_ms, ceil_ms from public.ski_board_floors f where f.board = new.game_id;
  if not found or new.score is null or new.score < floor_ms or new.score > coalesce(ceil_ms, 3600000) then
    if tg_op = 'UPDATE' then return old; end if;
    return null;
  end if;
  return new;
end $$;
revoke all on function public.ski_time_floor() from public, anon, authenticated;
-- runs before zz_catch_suspicious_score (triggers fire in name order)
drop trigger if exists ski_time_floor on public.scores;
create trigger ski_time_floor before insert or update on public.scores
  for each row execute function public.ski_time_floor();

-- H2: the per-player row cap of security-fix-scores-v1.sql, with the ski boards bounded by ski_board_floors instead (see 5. above).
-- KEEP IDENTICAL to the copy in scripts/security-fix-scores-v1.sql.
-- >>> scores_guard_row (scripts/ski/make_sql.py copies this block into ski-v1.sql: edit it HERE, then re-run make_sql.py)
-- Ski Alpen (ski-v1.sql, security review H2 22 Nov 2026): 1356 per-piste boards would hit the 300-row cap and silently stop every
-- game's saves. Once public.ski_board_floors exists, a ski-* row is allowed only for a board listed there and ski-* rows do not count
-- towards the 300. Before that table exists (ski-v1.sql not applied) ski-* ids are ordinary games. Safe to re-run in any order.
create or replace function public.scores_guard_row()
 returns trigger
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  c_max_rows constant integer := 300;
  c_max_name constant integer := 80;
  has_ski boolean := to_regclass('public.ski_board_floors') is not null;
begin
  if tg_op = 'UPDATE' then
    -- a score belongs to the game it was made in
    new.game_id := old.game_id;
    new.game_name := left(coalesce(new.game_name, old.game_name), c_max_name);
    return new;
  end if;
  if new.game_id is null
     or new.game_id !~ '^[a-z0-9][a-z0-9_-]{0,47}$' then
    return null;
  end if;
  new.game_name := left(new.game_name, c_max_name);
  -- An upsert of an existing row also passes here: only NEW boards count.
  if exists (select 1 from public.scores s
              where s.user_id = new.user_id
                and s.game_id = new.game_id) then
    return new;
  end if;
  if has_ski and new.game_id like 'ski-%' then
    if not exists (select 1 from public.ski_board_floors f where f.board = new.game_id) then
      return null;
    end if;
    return new;
  end if;
  if (select count(*) from public.scores s
       where s.user_id = new.user_id
         and (not has_ski or s.game_id not like 'ski-%')) >= c_max_rows then
    return null;
  end if;
  return new;
end $function$;

-- "aa_" so it runs before every other BEFORE trigger on scores.
drop trigger if exists aa_scores_guard_row on public.scores;
create trigger aa_scores_guard_row
  before insert or update on public.scores
  for each row execute function public.scores_guard_row();
-- <<< scores_guard_row

-- one row per piste board: length / 33 m/s, rounded down to whole seconds; one per snow park (stored points range)
on conflict (board) do update set min_ms = excluded.min_ms, max_ms = excluded.max_ms;
